-- Gallery media for the characters brought over from yuuki.
--
-- The characters came across but their galleries did not, so most of them
-- opened an empty gallery. Matched on the VRM filename, not the name: every
-- one of them was renamed on import (Emmie was Ayano, Rina was Yuina), so
-- matching by name would have handed one character's photos to another.
--
-- `is_nsfw OR should_hide` on yuuki's side becomes `should_hide` here, the
-- flag the sensitive-content gate reads. Existing rows are left alone: the
-- insert skips any url already present.
insert into public.medias
  (character_id, url, thumbnail, media_type, tier, price_ruby, should_hide,
   name, keywords, order_in_collection, available, content_type)
select v.character_id, v.url, v.thumbnail, v.media_type, v.tier,
       nullif(v.price_ruby, 0), v.should_hide, v.name, v.keywords, v.sort,
       true, 'normal'
